package com.fitbite.controller; import com.fitbite.dto.*; import com.fitbite.service.FavoriteService; import org.springframework.web.bind.annotation.*; import java.util.Map;
@RestController @RequestMapping("/api/favorites") public class FavoriteController{private final FavoriteService service;public FavoriteController(FavoriteService service){this.service=service;}@GetMapping public ApiResponse<?> list(){return ApiResponse.ok("Favorites fetched",service.list());}@PostMapping("/{recipeId}") public ApiResponse<?> add(@PathVariable Long recipeId){boolean added=service.toggle(recipeId);return ApiResponse.ok(added?"Recipe added to favorites":"Recipe removed from favorites",Map.of("favorite",added));}@DeleteMapping("/{recipeId}") public ApiResponse<Void> remove(@PathVariable Long recipeId){service.remove(recipeId);return ApiResponse.ok("Favorite removed",null);}}
